import{_ as d,o as r,c as n,ag as i,j as a,a as o,t as l}from"./chunks/framework.TQKaXlFR.js";const S=JSON.parse('{"title":"AI模型、提示词与业务场景","description":"","frontmatter":{},"headers":[],"relativePath":"features/ai.md","filePath":"features/ai.md"}'),s={name:"features/ai.md"};function p(t,e,u,m,c,T){return r(),n("div",null,[e[7]||(e[7]=i('<h1 id="ai模型、提示词与业务场景" tabindex="-1">AI模型、提示词与业务场景 <a class="header-anchor" href="#ai模型、提示词与业务场景" aria-label="Permalink to &quot;AI模型、提示词与业务场景&quot;">​</a></h1><p>入口为 <strong>通用能力 → AI模型、提示词场景</strong>。模型管理和场景设计需要平台身份及 <code>ai:model:*</code> / <code>ai:prompt:*</code> 精确权限；业务读取由代码注册的应用权限控制，不自动获得管理权限。</p><h2 id="模型操作" tabindex="-1">模型操作 <a class="header-anchor" href="#模型操作" aria-label="Permalink to &quot;模型操作&quot;">​</a></h2><p>在模型页点击“新增模型”，填写“供应方标识”“模型代号”“HTTPS 服务端点”“凭据环境变量名”“超时（秒）”，并选择启停状态。仅使用已获授权的模型信息。技术请求字段分别为providerCode、modelCode、endpointUrl、credentialEnvName、timeoutSeconds、enabled。凭据来源为ENV或加密DB，GET仅返回配置标记；数据库模式要求稳定CONFIG_MASTER_KEY。更新、启停、删除及凭据保存携带revision，冲突后重新读取，不覆盖他人的最新修改。</p><p>模型测试当前仅支持官方OpenRouter端点。点击模型行“测试模型”后，必须看结果内容，不能只看API返回200。当前Controller将测试Outcome放入Result.ok：例如外层HTTP200/code200，内层 <code>data.outcome=&quot;RATE_LIMITED&quot;</code>、<code>data.httpStatus=429</code>，代表供应方调用失败于限流。只有SUCCESS才是模型测试成功；AUTH_FAILED、MODEL_MISMATCH、TIMEOUT等各有不同恢复方式。测试可能调用外部供应商并产生计费，须在部署与授权明确后使用，不因教程示例自动发请求。</p><h2 id="场景流程" tabindex="-1">场景流程 <a class="header-anchor" href="#场景流程" aria-label="Permalink to &quot;场景流程&quot;">​</a></h2>',6)),a("ol",null,[e[2]||(e[2]=a("li",null,[o("打开新增场景草稿，在“应用标识”填写 "),a("code",null,"example_app"),o("、“场景标识”填写 "),a("code",null,"summary"),o("，选择一个已有“启用模型”。这里的example_app只是中性设计示例，未注册业务resolver时不能运行读取。")],-1)),a("li",null,[e[0]||(e[0]=o("在“提示词草稿”填写 ",-1)),a("code",null,"概述："+l(t.subject),1),e[1]||(e[1]=o("，点击“添加变量声明”，填写变量名subject，类型选择“文本”，用途说明填写“中性主题”，示例值填写“界面调整”。",-1))]),e[3]||(e[3]=a("li",null,"点击“保存草稿”，从列表“预览”进入“场景中性预览”，点击“生成中性预览”；应得到“概述：界面调整”。预览是文本渲染，不是模型调用，敏感变量会掩码。",-1)),e[4]||(e[4]=a("li",null,"点击列表“发布”并确认，详情中的“已发布快照”应出现版本。业务使用published版本；再次编辑“提示词草稿”不改变已发布内容。发布与启停使用revision。",-1))]),a("p",null,[e[5]||(e[5]=o("占位符使用 ",-1)),a("code",null,l(t.name),1),e[6]||(e[6]=o("；类型“文本/数字/布尔值”分别对应STRING/NUMBER/BOOLEAN，变量声明含description、sensitive、exampleValue。变量未声明、缺值或类型不符时先修正声明和输入，不把预览错误当成供应商连接错误。",-1))]),e[8]||(e[8]=i('<p>正文最长12000字符、最多64变量；单个预览/运行变量最长2048字符，exampleValue最长512。appKey/sceneKey创建后稳定，不能靠改名复用其他应用资源。</p><h2 id="业务读取与恢复" tabindex="-1">业务读取与恢复 <a class="header-anchor" href="#业务读取与恢复" aria-label="Permalink to &quot;业务读取与恢复&quot;">​</a></h2><p><code>POST /ai/scenes/{appKey}/{sceneKey}/render</code>只渲染已注册应用、已发布启用场景。接缝验证认证、业务动作、资源归属与租户，然后解析变量；不会直接发送模型请求或保存业务正文。未注册应用、缺变量、越权、停用场景与输出超长有明确拒绝结果。</p><p>没有证明两个独立业务系统已实际采用，也没有通用聊天、自动Agent或任意SQL/脚本变量能力。新业务注册方式见<a href="/xinghui-admin-vue3/docs/development/ai-extension.html">AI扩展</a>。</p><h2 id="源码依据" tabindex="-1">源码依据 <a class="header-anchor" href="#源码依据" aria-label="Permalink to &quot;源码依据&quot;">​</a></h2><ul><li>前端：<code>apps/web-ele/src/api/system/ai-model.ts</code>、<code>ai-prompt-scene.ts</code>及对应 <code>views/system/ai-model/index.vue</code>、<code>ai-prompt/index.vue</code>。</li><li>后端：<code>system-admin/src/main/java/com/xinghuiTec/ai/model/OpenRouterModelTester.java</code>、<code>ai/prompt/AiPromptSceneRules.java</code>、<code>ai/prompt/AiBusinessPromptRenderer.java</code>。</li><li>HTTP边界：<code>system-admin/src/main/java/com/xinghuiTec/controller/AiSceneReadController.java</code>。</li></ul>',6))])}const _=d(s,[["render",p]]);export{S as __pageData,_ as default};
